import os
from typing import Any, Dict, List, Optional

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import AnalyzeDocumentRequest
from azure.core.credentials import AzureKeyCredential


def extract_layout_elements(
    document_bytes: bytes,
    *,
    content_type: str = "application/pdf",
    model_id: str = "prebuilt-layout",
) -> Dict[str, Any]:
    endpoint = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    key = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_KEY")

    if not endpoint or not key:
        raise EnvironmentError(
            "AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT and AZURE_DOCUMENT_INTELLIGENCE_KEY must be set"
        )

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    poller = client.begin_analyze_document(
        model_id=model_id,
        body=AnalyzeDocumentRequest(bytes_source=document_bytes),
        content_type=content_type,
    )
    result = poller.result()

    def _span_text(spans: List[Any]) -> str:
        if not spans or not getattr(result, "content", None):
            return ""
        pieces = []
        for span in spans:
            offset = getattr(span, "offset", None)
            length = getattr(span, "length", None)
            if offset is None or length is None:
                continue
            pieces.append(result.content[offset : offset + length])
        return "".join(pieces).strip()

    pages_out: List[Dict[str, Any]] = []
    for page in getattr(result, "pages", []) or []:
        page_info: Dict[str, Any] = {
            "page_number": getattr(page, "page_number", None),
            "width": getattr(page, "width", None),
            "height": getattr(page, "height", None),
            "unit": getattr(page, "unit", None),
            "lines": [],
            "tables": [],
            "selection_marks": [],
        }

        for line in getattr(page, "lines", []) or []:
            page_info["lines"].append(
                {
                    "content": getattr(line, "content", None),
                    "polygon": [
                        {"x": getattr(p, "x", None), "y": getattr(p, "y", None)}
                        for p in (getattr(line, "polygon", None) or [])
                    ],
                    "spans": [
                        {"offset": getattr(s, "offset", None), "length": getattr(s, "length", None)}
                        for s in (getattr(line, "spans", None) or [])
                    ],
                }
            )

        for mark in getattr(page, "selection_marks", []) or []:
            page_info["selection_marks"].append(
                {
                    "state": getattr(mark, "state", None),
                    "confidence": getattr(mark, "confidence", None),
                    "polygon": [
                        {"x": getattr(p, "x", None), "y": getattr(p, "y", None)}
                        for p in (getattr(mark, "polygon", None) or [])
                    ],
                }
            )

        pages_out.append(page_info)

    tables_out: List[Dict[str, Any]] = []
    for table in getattr(result, "tables", []) or []:
        cells_out: List[Dict[str, Any]] = []
        for cell in getattr(table, "cells", []) or []:
            cells_out.append(
                {
                    "row_index": getattr(cell, "row_index", None),
                    "column_index": getattr(cell, "column_index", None),
                    "row_span": getattr(cell, "row_span", None),
                    "column_span": getattr(cell, "column_span", None),
                    "content": getattr(cell, "content", None),
                    "kind": getattr(cell, "kind", None),
                    "spans": [
                        {"offset": getattr(s, "offset", None), "length": getattr(s, "length", None)}
                        for s in (getattr(cell, "spans", None) or [])
                    ],
                }
            )

        tables_out.append(
            {
                "row_count": getattr(table, "row_count", None),
                "column_count": getattr(table, "column_count", None),
                "cells": cells_out,
                "bounding_regions": [
                    {
                        "page_number": getattr(br, "page_number", None),
                        "polygon": [
                            {"x": getattr(p, "x", None), "y": getattr(p, "y", None)}
                            for p in (getattr(br, "polygon", None) or [])
                        ],
                    }
                    for br in (getattr(table, "bounding_regions", None) or [])
                ],
            }
        )

    paragraphs_out: List[Dict[str, Any]] = []
    for paragraph in getattr(result, "paragraphs", []) or []:
        paragraphs_out.append(
            {
                "content": getattr(paragraph, "content", None),
                "role": getattr(paragraph, "role", None),
                "spans": [
                    {"offset": getattr(s, "offset", None), "length": getattr(s, "length", None)}
                    for s in (getattr(paragraph, "spans", None) or [])
                ],
                "bounding_regions": [
                    {
                        "page_number": getattr(br, "page_number", None),
                        "polygon": [
                            {"x": getattr(p, "x", None), "y": getattr(p, "y", None)}
                            for p in (getattr(br, "polygon", None) or [])
                        ],
                    }
                    for br in (getattr(paragraph, "bounding_regions", None) or [])
                ],
            }
        )

    return {
        "content": getattr(result, "content", None),
        "pages": pages_out,
        "tables": tables_out,
        "paragraphs": paragraphs_out,
    }
